use vstd::prelude::*;

verus! {

fn reverse(a: &mut Vec<i32>)
    ensures
        a@ == old(a)@.reverse(),
{
    let mut i: usize = 0;
    let mut j: usize = a.len();

    while i < j
        invariant
            // Indices are in-bounds w.r.t. the original length
            j <= a.len(),
            i <= j,
            a@.len() == old(a)@.len(),

            // Left part already reversed into place
            forall|k: int| 0 <= k < i as int ==>
                a@[k] == old(a)@[old(a)@.len() - 1 - k],

            // Right part already reversed into place
            forall|k: int| j as int <= k < a@.len() ==>
                a@[k] == old(a)@[old(a)@.len() - 1 - k],

            // Middle part (between i and j) is still some permutation of the original middle
            // (captured as a multiset equality)
            a@.subrange(i as int, j as int).to_multiset()
                == old(a)@.subrange(i as int, j as int).to_multiset(),
        decreases j - i,
    {
        j -= 1;
        if i >= j {
            break;
        }

        // Swapping preserves multiset of the middle, and it places two boundary elements correctly.
        a.swap(i, j);

        i += 1;
    }
}

} // verus!

